const tabId = 730410078;
const apiData = await browserjs(tabId, async () => {
  try {
    const res = await fetch('/api/camps/availability/campground/232512/month?start_date=2026-09-01T00%3A00%3A00.000Z');
    if (!res.ok) return { error: res.status, statusText: res.statusText };
    const json = await res.json();
    return json;
  } catch (e) {
    return { error: e.message };
  }
});

console.log("Campsites count:", Object.keys(apiData.campsites || {}).length);
// Let's inspect one campsite's availability
const firstKey = Object.keys(apiData.campsites || {})[0];
console.log("First campsite sample:", firstKey, JSON.stringify(apiData.campsites?.[firstKey], null, 2));

const tabId = 730410078;
const analysis = await browserjs(tabId, async () => {
  const res = await fetch('/api/camps/availability/campground/232512/month?start_date=2026-09-01T00%3A00%3A00.000Z');
  const data = await res.json();

  const siteAvail = {};
  for (const [id, site] of Object.entries(data.campsites)) {
    for (const [dateStr, status] of Object.entries(site.availabilities)) {
      const d = dateStr.split('T')[0];
      if (!siteAvail[d]) siteAvail[d] = { Available: 0, NotReservable: 0, Reserved: 0, other: 0 };
      if (status === 'Available') siteAvail[d].Available++;
      else if (status === 'Not Reservable') siteAvail[d].NotReservable++;
      else if (status === 'Reserved') siteAvail[d].Reserved++;
      else siteAvail[d].other++;
    }
  }
  return siteAvail;
});

console.log(JSON.stringify(analysis, null, 2));

